PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS boards(id INTEGER PRIMARY KEY, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, subtitle TEXT NOT NULL DEFAULT '', locked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS posts(id INTEGER PRIMARY KEY AUTOINCREMENT, board_id INTEGER NOT NULL REFERENCES boards(id) ON DELETE CASCADE, thread_id INTEGER REFERENCES posts(id) ON DELETE CASCADE, name TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, created INTEGER NOT NULL, bumped INTEGER NOT NULL, edited INTEGER, sticky INTEGER NOT NULL DEFAULT 0, locked INTEGER NOT NULL DEFAULT 0, deletion_hash TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS posts_board ON posts(board_id,thread_id,sticky DESC,bumped DESC);
CREATE INDEX IF NOT EXISTS posts_thread ON posts(thread_id,id);
CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY, post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE, token TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, mime TEXT NOT NULL, extension TEXT NOT NULL, bytes INTEGER NOT NULL, width INTEGER NOT NULL DEFAULT 0, height INTEGER NOT NULL DEFAULT 0, thumb INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS staff(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','moderator','janitor')), version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS reports(id INTEGER PRIMARY KEY, post_id INTEGER NOT NULL REFERENCES posts(id) ON DELETE CASCADE, reason TEXT NOT NULL, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS reports_post ON reports(post_id);
CREATE TABLE IF NOT EXISTS audit(id INTEGER PRIMARY KEY, actor INTEGER, action TEXT NOT NULL, target TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS throttle(scope TEXT NOT NULL, bucket INTEGER NOT NULL, hits INTEGER NOT NULL, expires INTEGER NOT NULL, PRIMARY KEY(scope,bucket));
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
